'use strict';

/**
 * The single authoring source for composition.
 *
 * A capability used to be declared in the registry, listed again in up to
 * three manifests, and described a fourth time in the frontend surface
 * registry of another repository. Four places meant four chances to drift.
 * Here one record carries the capability, its pack membership, and the
 * surfaces that present it, and the rest is generated.
 *
 * The generated files stay checked in because the type system reads them:
 * CapabilityKey is derived from the literal keys in the registry, so the
 * compiler still rejects an unknown key anywhere in the backend.
 */

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..', '..');
const COMPOSITION_DIR = path.join(ROOT, 'src', 'kernel', 'composition');
const SOURCE_PATH = path.join(COMPOSITION_DIR, 'catalog.source.json');
const REGISTRY_PATH = path.join(COMPOSITION_DIR, 'capability-registry.ts');
const MANIFESTS_PATH = path.join(COMPOSITION_DIR, 'manifests.ts');

const EDITIONS = ['saas', 'edu', 'enterprise'];
const MATURITIES = ['stable', 'limited', 'not-implemented'];
const KEY_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*\.[a-z0-9]+(?:-[a-z0-9]+)*$/;
const CONSTANT_BY_EDITION = {
  saas: 'SAAS_KEYS',
  edu: 'EDU_KEYS',
  enterprise: 'ENTERPRISE_KEYS',
};

const HEADER = [
  '// Generated from catalog.source.json by scripts/generate-composition-source.mjs.',
  '// Edit the source record and run npm run generate:composition.',
  '// Do not edit this file by hand.',
].join('\n');

function loadSource(file = SOURCE_PATH) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function isStringArray(value) {
  return Array.isArray(value) && value.every((entry) => typeof entry === 'string');
}

/**
 * Validate the authoring source before anything is generated from it.
 *
 * The dependency rules are the ones a resolver would otherwise apply in
 * silence: a capability whose dependency is missing from its own pack is
 * dropped at runtime, which looks like a capability that simply does not work.
 * Catching it here makes it an authoring error instead of a mystery.
 */
function validateSource(source) {
  const errors = [];
  if (source === null || typeof source !== 'object' || !Array.isArray(source.capabilities)) {
    return ['catalog.source.json must contain a capabilities array'];
  }
  if (source.capabilities.length === 0) {
    return ['catalog.source.json must declare at least one capability'];
  }

  const byKey = new Map();
  source.capabilities.forEach((record, index) => {
    const at = record && typeof record.key === 'string' ? record.key : 'entry ' + index;
    if (record === null || typeof record !== 'object') {
      errors.push(at + ': must be an object');
      return;
    }
    if (typeof record.key !== 'string' || !KEY_PATTERN.test(record.key)) {
      errors.push(at + ': key must be lowercase context.name');
    } else if (byKey.has(record.key)) {
      errors.push(at + ': duplicate key');
    } else {
      byKey.set(record.key, record);
    }
    if (typeof record.context !== 'string' || record.context.trim() === '') {
      errors.push(at + ': context is required');
    }
    if (typeof record.description !== 'string' || record.description.trim() === '') {
      errors.push(at + ': description is required');
    }
    if (!MATURITIES.includes(record.maturity)) {
      errors.push(at + ': maturity must be one of ' + MATURITIES.join(', '));
    }
    if (typeof record.configuration !== 'string' || record.configuration.trim() === '') {
      errors.push(at + ': configuration is required, including when it records that no flag exists');
    }
    if (!isStringArray(record.configurationFlags)) {
      errors.push(at + ': configurationFlags must be an array of strings');
    }
    if (!isStringArray(record.requires)) {
      errors.push(at + ': requires must be an array of strings');
    }
    if (!isStringArray(record.editions) || record.editions.some((edition) => !EDITIONS.includes(edition))) {
      errors.push(at + ': editions must be drawn from ' + EDITIONS.join(', '));
    } else {
      const canonical = EDITIONS.filter((edition) => record.editions.includes(edition));
      if (canonical.join(',') !== record.editions.join(',')) {
        errors.push(at + ': editions must be listed as ' + EDITIONS.join(', '));
      }
    }
    errors.push(...surfaceErrors(at, record.surface));
  });

  for (const [key, record] of byKey) {
    if (!Array.isArray(record.requires)) continue;
    for (const dependency of record.requires) {
      if (dependency === key) {
        errors.push(key + ': cannot require itself');
        continue;
      }
      const target = byKey.get(dependency);
      if (target === undefined) {
        errors.push(key + ": requires unknown capability '" + dependency + "'");
        continue;
      }
      if (!Array.isArray(record.editions) || !Array.isArray(target.editions)) continue;
      for (const edition of record.editions) {
        if (!target.editions.includes(edition)) {
          errors.push(
            key + " is in '" + edition + "' but its dependency '" + dependency + "' is not",
          );
        }
      }
    }
  }

  errors.push(...cycleErrors(byKey));
  return errors;
}

function surfaceErrors(at, surface) {
  if (surface === null || typeof surface !== 'object' || Array.isArray(surface)) {
    return [at + ': surface must be an object'];
  }
  const errors = [];
  for (const field of ['apiField', 'viewFlag']) {
    const value = surface[field];
    if (value !== null && typeof value !== 'string') {
      errors.push(at + ': surface.' + field + ' must be a string or null');
    }
  }
  for (const field of ['domains', 'routes', 'featureBarrels']) {
    if (!isStringArray(surface[field])) {
      errors.push(at + ': surface.' + field + ' must be an array of strings');
    }
  }
  if (surface.artifactSymbols !== undefined && !isStringArray(surface.artifactSymbols)) {
    errors.push(at + ': surface.artifactSymbols must be an array of strings');
  }
  return errors;
}

function cycleErrors(byKey) {
  const errors = [];
  const state = new Map();
  const visit = (key, trail) => {
    if (state.get(key) === 'done') return;
    if (state.get(key) === 'open') {
      errors.push('dependency cycle: ' + [...trail, key].join(' -> '));
      return;
    }
    state.set(key, 'open');
    const record = byKey.get(key);
    for (const dependency of Array.isArray(record?.requires) ? record.requires : []) {
      if (byKey.has(dependency)) visit(dependency, [...trail, key]);
    }
    state.set(key, 'done');
  };
  for (const key of byKey.keys()) visit(key, []);
  return errors;
}

function renderRegistry(source) {
  const records = source.capabilities.map((record) =>
    [
      '  {',
      '    key: ' + JSON.stringify(record.key) + ',',
      '    context: ' + JSON.stringify(record.context) + ',',
      '    description: ' + JSON.stringify(record.description) + ',',
      '    maturity: ' + JSON.stringify(record.maturity) + ',',
      '    configuration: ' + JSON.stringify(record.configuration) + ',',
      '    configurationFlags: ' + JSON.stringify(record.configurationFlags) + ',',
      '    requires: ' + JSON.stringify(record.requires) + ',',
      '  },',
    ].join('\n'),
  );

  return [
    HEADER,
    '',
    "import type { CapabilityRecord } from './capability-record.types.js';",
    '',
    'export const CAPABILITIES = [',
    ...records,
    '] as const satisfies readonly CapabilityRecord[];',
    '',
  ].join('\n');
}

function renderManifests(source) {
  const blocks = EDITIONS.map((edition) => {
    const keys = source.capabilities
      .filter((record) => record.editions.includes(edition))
      .map((record) => '  ' + JSON.stringify(record.key) + ',');
    return ['const ' + CONSTANT_BY_EDITION[edition] + ' = [', ...keys, '] as const;'].join('\n');
  });

  const entries = EDITIONS.map(
    (edition) =>
      '  ' +
      edition +
      ': { edition: ' +
      JSON.stringify(edition) +
      ', capabilities: ' +
      CONSTANT_BY_EDITION[edition] +
      ' },',
  );

  return [
    HEADER,
    '',
    "import type { CapabilityManifest, Edition } from './capability-types.js';",
    '',
    blocks.join('\n\n'),
    '',
    'export const PACK_MANIFESTS = {',
    ...entries,
    '} as const satisfies Record<Edition, CapabilityManifest>;',
    '',
  ].join('\n');
}

module.exports = {
  EDITIONS,
  MANIFESTS_PATH,
  MATURITIES,
  REGISTRY_PATH,
  SOURCE_PATH,
  loadSource,
  renderManifests,
  renderRegistry,
  validateSource,
};
